function HomelandCheckInEntryGroupNode:Awake()
    ---@type HomelandCheckInComponent
    self.comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HomelandCheckInComponent)
    if isNotNull(self.Root) then
        SetButtonAction(self.Root.gameObject, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.HomelandCheckInDialog, parameters = {groupId = self.data.groupId}})
        end)
    end
    if isNotNull(self.Btnmagnifier) then
        SetButtonAction(self.Btnmagnifier.gameObject, function()
            KTool.SetActive(self.CombatantBonusTips, true)
            local lb = GetLuaBehaviour(self.CombatantBonusTips.gameObject, AdditionalDetailLuaPath)
            if isNotNull(lb) then
                lb.Env:Refresh(self.data.groupId)
            end
        end)
    end
end

