function HomelandCheckInEntryGroupNode:CleanProperties()
    ---@type CheckInGroupVo
    self.data = nil
    self.comp = nil
end

function HomelandCheckInEntryGroupNode:Refresh(data)
    if isNull(data) then
        return
    end
    self.data = data

    local groupId = data.groupId
    if groupId <= 0 then
        return
    end

    CfUtils.FillText(self.TxtTeamName, data.name)

    local imgPath = string.isEmpty(data.pic) and string.format(ImgPathPatten, groupId) or data.pic
    CfUtils.FillImage(self.ImgTeamIcon.gameObject, imgPath)

    local cardNum, cardNumMax, starNum, starNumMax = self.comp:GetCardNumAndStarNum(groupId)

    CfUtils.FillText(self.TxtStar, string.format("%d/%d", starNum, starNumMax))
    CfUtils.FillText(self.TxtPeople, string.format("%d/%d", cardNum, cardNumMax))

    local level = self.comp:GetGroupLevel(groupId)
    local levelMax = self.comp:GetGroupUpgradeLevelMax(groupId)
    local isLevelMax = level >= levelMax
    -- print("[信息录入] 小队", level, levelMax, isLevelMax)

    CfUtils.SetUISwitchImage(self.ImgColorBg.gameObject, isLevelMax and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgColorFrame.gameObject, isLevelMax and 2 or 1)
    CfUtils.SetUISwitchText(self.TxtLv.gameObject, isLevelMax and 2 or 1)

    local levelText = string.format("<size=55>lv</size>.%s", isLevelMax and "MAX" or tostring(level))
    CfUtils.FillText(self.TxtLv, levelText)
end

return HomelandCheckInEntryGroupNode